changing basis. 7.3.5 Property 5: Determinant \[\det(\exp(X)) = \exp(	ext{tr}(X))\] This is a fundamental property connecting the determinant, trace, and exponential. det_expX &lt;- det(expm(X)) exp_trX &lt;- exp(sum(diag(X))) prop5_error &lt;- abs(det_expX - exp_trX) prop5_verified &lt;- prop5_error &lt; 1e-10 Result: TRUE \(\det(\exp(X)) = 0.32691968\) \(\exp(	ext{tr}(X)) = 0.32691968\) Error: 5.55e-17 Corollary: \(\exp(X)\) is always invertible since \(\det(\exp(X)) = e^{	ext{tr}(X)} 
eq 0\). 7.3.6 Property 6: Commuting Matrices If \([X,Y] = XY - YX = 0\), then: \[\exp(X+Y) = \exp(X)\exp(Y)\] # Use diagonal matrices (always commute) D1 &lt;- diag(c(1, 2, 3)) D2 &lt;- diag(c(4, 5, 6)) commutator_D &lt;- D1 %*% D2 - D2 %*% D1 prop6_error &lt;- max(abs(expm(D1 + D2) - expm(D1) %*% expm(D2))) prop6_verified &lt;- prop6_error &lt; 1e-10 # Counter-example: non-commuting matrices X_nc &lt;- matrix(c(1, 2, 0, 3), 2, 2) Y_nc &lt;- matrix(c(0, 1, 1, 0), 2, 2) commutator_nc &lt;- X_nc %*% Y_nc - Y_nc %*% X_nc error_nc &lt;- max(abs(expm(X_nc + Y_nc) - expm(X_nc) %*% expm(Y_nc))) Commuting case: TRUE (Error: 9.55e-11) Non-commuting case: \(||[X,Y]|| = 4.0000\) (non-zero) \(||\exp(X+Y) - \exp(X)\exp(Y)|| = 10.2050\) (large error) This demonstrates that the product rule fails for non-commuting matrices. 7.3.7 Property 7: Lie Product Formula For any \(X, Y \in M_n(\mathbb{C})\): \[\exp(X+Y) = \lim_{m 	o \infty} (\exp(X/m)\exp(Y/m))^m\] X2 &lt;- matrix(rnorm(4), 2, 2) Y2 &lt;- matrix(rnorm(4), 2, 2) # Test convergence for different values of m m_values &lt;- c(10, 20, 50, 100, 200, 500, 1000) errors_lie &lt;- sapply(m_values, function(m) { lie_prod &lt;- Reduce(`%*%`, replicate(m, expm(X2/m) %*% expm(Y2/m), simplify = FALSE)) direct &lt;- expm(X2 + Y2) return(norm(lie_prod - direct, &quot;F&quot;)) }) lie_df &lt;- data.frame( m = m_values, Error = errors_lie, Rate = c(NA, errors_lie[-1] / errors_lie[-length(errors_lie)]) ) ggplot(lie_df, aes(x = m, y = Error)) + geom_line(color = &quot;blue&quot;, size = 1.2) + geom_point(color = &quot;red&quot;, size = 3) + scale_x_log10() + scale_y_log10() + labs(title = &quot;Lie Product Formula Convergence&quot;, subtitle = sprintf(&quot;||[X,Y]|| = %.3f&quot;, norm(X2 %*% Y2 - Y2 %*% X2, &quot;F&quot;)), x = &quot;m (log scale)&quot;, y = &quot;Error (log scale)&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;)) kable(lie_df, digits = 8, caption = &quot;Lie Product Formula Convergence&quot;, col.names = c(&quot;m&quot;, &quot;Error&quot;, &quot;Error Ratio&quot;)) %&gt;% kable_styling(bootstrap_options = c(&quot;striped&quot;, &quot;hover&quot;)) Table 7.2: Lie Product Formula Convergence m Error Error Ratio 10 0.30646407 NA 20 0.15344262 0.5006871 50 0.06143206 0.4003585 100 0.03072556 0.5001551 200 0.01536519 0.5000786 500 0.00614666 0.4000380 1000 0.00307343 0.5000159 Analysis: The error decreases approximately as \(O(1/m)\), consistent with theoretical predictions. This formula is crucial for numerical simulation of quantum systems. 7.3.8 Summary: Theorem 4.1 theorem_summary &lt;- data.frame( Property = c( &quot;1. exp(0) = I&quot;, &quot;2. exp(X^T) = (exp(X))^T&quot;, &quot;3. exp(X*) = (exp(X))*&quot;, &quot;4. Conjugation&quot;, &quot;5. det(exp(X)) = exp(tr(X))&quot;, &quot;6. Commuting: exp(X+Y) = exp(X)exp(Y)&quot;, &quot;7. Lie Product Formula&quot; ), Verified = c(prop1_verified, prop2_verified, prop3_verified, prop4_verified, prop5_verified, prop6_verified, TRUE), Error = c(0, prop2_error, prop3_error, prop4_error, prop5_error, prop6_error, errors_lie[length(errors_lie)]) ) kable(theorem_summary, digits = 12, caption = &quot;Summary of Theorem 16.15 Verification&quot;, col.names = c(&quot;Property&quot;, &quot;Verified&quot;, &quot;Numerical Error&quot;)) %&gt;% kable_styling(bootstrap_options = c(&quot;striped&quot;, &quot;hover&quot;)) %&gt;% column_spec(2, bold = TRUE, color = ifelse(theorem_summary$Verified, &quot;green&quot;, &quot;red&quot;)) Table 7.3: Summary of Theorem 16.15 Verification Property Verified Numerical Error exp(0) = I TRUE 0.000000e+00 exp(X^T) = (exp(X))^T TRUE 0.000000e+00 exp(X) = (exp(X)) TRUE 0.000000e+00 Conjugation TRUE 0.000000e+00 det(exp(X)) = exp(tr(X)) TRUE 0.000000e+00 Commuting: exp(X+Y) = exp(X)exp(Y) TRUE 9.500000e-11 Lie Product Formula TRUE 3.073428e-03 All seven properties are verified within numerical precision, confirming the theoretical results. 7.4 Baker-Campbell-Hausdorff Formula 7.4.1 Background For sufficiently small \(X, Y \in M_n(\mathbb{C})\):\[e^X e^Y = e^{Z}\] where \[Z = X + Y +  rac{1}{2}[X,Y] +  rac{1}{12}[X,[X,Y]] -  rac{1}{12}[Y,[X,Y]] + \cdots\] The series converges when \(\|X\|\) and \(\|Y\|\) are sufficiently small. 7.4.2 Implimentation ## Lie bracket (commutator) commutator &lt;- function(X, Y) X %*% Y - Y %*% X bch_expansion &lt;- function(X, Y, order = 4) { Z &lt;- X + Y if (order &gt;= 2) Z &lt;- Z + 0.5 * commutator(X, Y) if (order &gt;= 3) { Z &lt;- Z + (1/12) * commutator(X, commutator(X, Y)) Z &lt;- Z - (1/12) * commutator(Y, commutator(X, Y)) } if (order &gt;= 4) { Z &lt;- Z - (1/24) * commutator(Y, commutator(X, commutator(X, Y))) } if (order &gt;=5){ Z &lt;- Z - (1/720) * commutator(Y, commutator(Y, commutator(Y, commutator(X, Y)))) Z &lt;- Z + (1/180) * commutator(X, commutator(Y, commutator(Y, commutator(X, Y)))) } return(Z) } 7.4.3 Convergence Analysis scale &lt;- 0.1 set.seed(500) X &lt;- scale * matrix(rnorm(9), 3, 3) Y &lt;- scale * matrix(rnorm(9), 3, 3) direct &lt;- expm(X) %*% expm(Y) errors &lt;- sapply(1:5, function(o) { norm(direct - expm(bch_expansion(X, Y, o)), &quot;F&quot;) }) ggplot(data.frame(Order = 1:5, Error = errors), aes(x = Order, y = Error)) + geom_line(color = &quot;blue&quot;, size = 1.5) + geom_point(color = &quot;red&quot;, size = 3) + scale_y_log10() + labs(title = &quot;BCH Convergence&quot;, y = &quot;Error (log scale)&quot;) + theme_minimal() # Test 1: Convergence by order scale &lt;- 0.05 set.seed(1000) X &lt;- scale * matrix(rnorm(9), 3, 3) Y &lt;- scale * matrix(rnorm(9), 3, 3) direct &lt;- expm(X) %*% expm(Y) cat(sprintf(&quot;Test matrices: scale = %.3f
